#: Nodes classified by the registry but not yet implemented. Kept in sync
#: with docs/API_CONTRACTS.md. If a KNOWN_FUTURE node lands, remove it here.
KNOWN_FUTURE_NODES = frozenset({
    "flow.merge",
    "flow.wait",
    "flow.loop_batch",
    "flow.subflow",
    "flow.retry",
    "utils.notify",
})


# ---------------------------------------------------------------------------
# H1 — discovery completeness
# ---------------------------------------------------------------------------

def test_discover_plugins_covers_all_classified_nodes() -> None:
    registered = set(discover_plugins())
    expected = set(DEFAULT_OPERATION_MAP) - KNOWN_FUTURE_NODES
    missing = expected - registered
    assert not missing, (
        f"classified nodes not registered: {sorted(missing)}. "
        f"If a KNOWN_FUTURE node just landed, remove it from "
        f"KNOWN_FUTURE_NODES."
    )


# ---------------------------------------------------------------------------
# H7 — no premature classification
# ---------------------------------------------------------------------------

def test_no_premature_classification() -> None:
    ghosts = (
        set(DEFAULT_OPERATION_MAP)
        - set(discover_plugins())
        - KNOWN_FUTURE_NODES
    )
    assert not ghosts, (
        f"ghost ids in DEFAULT_OPERATION_MAP — classified but neither "
        f"registered nor declared KNOWN_FUTURE: {sorted(ghosts)}"
    )


# ---------------------------------------------------------------------------
# M3 — NODE_CHANGE_KIND covers every fs.* op
# ---------------------------------------------------------------------------

def test_node_change_kind_covers_all_fs_ops() -> None:
    fs_ids = {n for n in DEFAULT_OPERATION_MAP if n.startswith("fs.")}
    uncovered = fs_ids - set(NODE_CHANGE_KIND)
    assert not uncovered, (
        f"fs.* node ids missing from NODE_CHANGE_KIND: {sorted(uncovered)}"
    )


# ---------------------------------------------------------------------------
# M5 — ResolvedGraph.__post_init__ rejects ghost ids
# ---------------------------------------------------------------------------

def _doc_with_nodes(*ids: str) -> WorkflowDocument:
    return WorkflowDocument(
        spec_version="1.0",
        metadata=WorkflowMetadata(id="test"),
        nodes=[NodeSpec(id=i, type="utils.path_template") for i in ids],
    )


def test_resolved_graph_rejects_ghost_ids() -> None:
    doc = _doc_with_nodes("real")
    with pytest.raises(ValueError, match="ordered_node_ids references"):
        ResolvedGraph(
            document=doc,
            ordered_node_ids=["real", "ghost"],
            handlers={},
            states={},
        )


def test_resolved_graph_accepts_valid_ids() -> None:
    doc = _doc_with_nodes("real")
    graph = ResolvedGraph(
        document=doc,
        ordered_node_ids=["real"],
        handlers={},
        states={},
    )
    assert graph.ordered_node_ids == ["real"]


# ---------------------------------------------------------------------------
# L4 — safe_fs.py docstring lists every allowed module
# ---------------------------------------------------------------------------

#: Source of truth: tests/test_architecture.py — keep in sync.
READONLY_FS_ALLOWED = frozenset({
    "core/audit.py",
    "core/config.py",
    "core/executor/context.py",
    "core/graph/validator.py",
    "core/paths.py",
    "core/scope.py",
})
MUTATION_FS_ALLOWED = frozenset({"core/logging.py"})


def test_safe_fs_docstring_lists_all_allowed_modules() -> None:
    safe_fs_path = (
        Path(__file__).resolve().parents[1]
        / "src" / "lokdocsqr" / "core" / "safe_fs.py"
    )
    src = safe_fs_path.read_text(encoding="utf-8")
    # AST is used ONLY to extract the module docstring (task rule for L4).
    docstring = ast.get_docstring(ast.parse(src))
    assert docstring is not None, "safe_fs.py must have a module docstring"
    normalized = docstring.replace("\\", "/")

    missing = [
        rel
        for rel in sorted(READONLY_FS_ALLOWED | MUTATION_FS_ALLOWED)
        if rel not in normalized
    ]
    assert not missing, (
        f"safe_fs.py docstring is out of sync with test_architecture.py; "
        f"missing: {missing}"
    )

    assert "preview.py" not in normalized, (
        "safe_fs.py docstring must not mention preview.py any more"
    )


